string primName = chs("primpattern");
matrix camMat = usd_localtransform(0, primName);
vector camP = cracktransform(0, 0, 0, 0, camMat);

matrix focMat = usd_localtransform(0, primName+"_focus_point");
vector focP = cracktransform(0, 0, 0, 0, focMat);

usd_setattrib(0, primName, "focusDistance", distance(camP, focP));
